import{_ as e,c as t,o as a,N as r}from"./chunks/framework.0Wz7YRG7.js";const m=JSON.parse('{"title":"Security Model","description":"","frontmatter":{"title":"Security Model","order":1,"outline":[0,4]},"headers":[],"relativePath":"products/ultra-web-wallet/security.md","filePath":"products/ultra-web-wallet/security.md","lastUpdated":null}'),i={name:"products/ultra-web-wallet/security.md"},o=r('<h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><p>The Ultra Web Wallet is non-custodial: transaction and message signing happens in the user&#39;s browser, and Ultra does not store the complete private key.</p><h2 id="key-generation-and-storage" tabindex="-1">Key generation and storage <a class="header-anchor" href="#key-generation-and-storage" aria-label="Permalink to &quot;Key generation and storage&quot;">​</a></h2><p>When a browser device is registered, the Web Wallet generates the private/public key pair locally. It sends the public key for registration with the user&#39;s EBA account and saves the private key in an encrypted vault in the Web Wallet origin&#39;s local browser storage.</p><p>The vault encryption key is assembled from two parts during authentication:</p><ul><li>A user/device part retained in the Web Wallet&#39;s local storage in encrypted form.</li><li>An Ultra part returned by the device activation service after the user authenticates.</li></ul><p>Neither the encrypted local vault nor Ultra&#39;s server-side part is sufficient on its own to recover the private key. This model still depends on the security of the user&#39;s browser, device, Ultra account, and the Web Wallet service; it should not be treated as protection against every form of compromise.</p><p>Clearing site data for the Web Wallet removes its local device and vault data. The user may need to register the browser as a new device on the next connection.</p><h2 id="authentication-and-device-registration" tabindex="-1">Authentication and device registration <a class="header-anchor" href="#authentication-and-device-registration" aria-label="Permalink to &quot;Authentication and device registration&quot;">​</a></h2><p>The popup authenticates through Ultra SSO. A new device registers its generated public key with the EBA service and waits until the account/device update is confirmed before enabling signing. Some device-management operations can require a higher SSO authentication level.</p><p>The Web Wallet currently supports EBA accounts only.</p><h2 id="dapp-permissions-and-request-approval" tabindex="-1">dApp permissions and request approval <a class="header-anchor" href="#dapp-permissions-and-request-approval" aria-label="Permalink to &quot;dApp permissions and request approval&quot;">​</a></h2><p>The Web Wallet stores approved dApp origins locally for each signed-in user. A previously approved origin can reconnect silently; disconnecting removes that local approval.</p><p>Message and transaction requests are shown in the Web Wallet for user approval. Messages must begin with <code>message:</code>, <code>0x</code>, or <code>UOSx</code>. Transactions are broadcast only after approval unless the dApp requests <code>signOnly</code>, in which case the signed transaction is returned without broadcasting.</p><h2 id="communication-boundary" tabindex="-1">Communication boundary <a class="header-anchor" href="#communication-boundary" aria-label="Permalink to &quot;Communication boundary&quot;">​</a></h2><p>The SDK and Web Wallet exchange JSON-RPC messages through the popup. The SDK sends requests only to the configured wallet origin and accepts responses only from that origin. The Web Wallet binds a popup session to the origin that initiated the request and sends its response back to that origin.</p><h2 id="developer-practices" tabindex="-1">Developer practices <a class="header-anchor" href="#developer-practices" aria-label="Permalink to &quot;Developer practices&quot;">​</a></h2><ul><li>Use the official <code>@ultraos/wallet-sdk</code> package.</li><li>Set the intended <code>environment</code> explicitly and use <code>provider: &#39;web&#39;</code> when the Web Wallet is required rather than an automatic fallback.</li><li>Invoke popup-opening methods directly from a user gesture.</li><li>Display the transaction details in the dApp before opening the wallet, and treat rejected or closed requests as normal outcomes.</li><li>Do not request signatures for opaque data that users cannot independently understand.</li><li>Avoid retaining signed payloads longer than the application requires.</li></ul>',18),n=[o];function s(l,c,d,p,u,h){return a(),t("div",null,n)}const b=e(i,[["render",s]]);export{m as __pageData,b as default};
